"""
    :param letter_qty: how many letters are key in
    :return: total arrangement qty
    """
def factorial(letter_qty: Any) -> object {
    if (letter_qty == 0) {
        return 1;
    } else {
        temp = letter_qty * factorial((letter_qty - 1));
        return temp;
    }
}

